urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {%- set meta_date = file.page.meta.date if file.page.meta.date is defined and file.page.meta.date else none %}
         {%- set lastmod = meta_date.split(' ')[0] if meta_date else file.page.update_date %}
         {% if lastmod %}{{ lastmod }}{% endif %}

    {%- endif -%}
{% endfor %}
